for(const n of ['Pinnacle Starcage','Mount Doom','Dermotaxi','Boseiju, Who Endures','Eater of Virtue','Godsend'])implemented.add(n);for(const n of ['Urban Retreat','The Millennium Calendar','Jeweled Amulet'])implemented.add(n);for(const n of ["Summoner's Grimoire","Ninja's Blades",'Mjölnir, Hammer of Thor'])implemented.add(n);for(const n of ['Doors of Durin','Rakdos Riteknife','Booby Trap'])implemented.add(n);for(const n of ["Liar's Pendulum","Theorist's Sanctum",'Shuriken'])implemented.add(n);implemented.add('Damping Sphere');implemented.add('Archway of Innovation');implemented.add('Glowcap Lantern');
